// frontend/src/services/api.js
import axios from "axios";

const api = axios.create({
  baseURL: "http://localhost:5000/api", // Ensure this is your backend URL
  headers: {
    "Content-Type": "application/json",
  },
});

// Request interceptor to attach JWT token
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem("tripto_token");
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Response interceptor to handle 401 errors (e.g., token expired)
api.interceptors.response.use(
  (response) => {
    // Any status code that lie within the range of 2xx cause this function to trigger
    return response;
  },
  (error) => {
    // Any status codes that falls outside the range of 2xx cause this function to trigger
    if (error.response && error.response.status === 401) {
      console.warn("Axios Interceptor: Received 401 Unauthorized. Token might be expired or invalid.");
      
      // Perform logout actions:
      localStorage.removeItem("tripto_user");
      localStorage.removeItem("tripto_token");

      // Dispatch a custom event that App.jsx can listen to, to update its state
      // This is a simple way to communicate across components without prop drilling for this specific case.
      // More complex apps might use Context or a state management library (Redux, Zustand).
      window.dispatchEvent(new CustomEvent("auth-expired"));
      
      // Optionally, you could redirect to login page here, but letting App.jsx handle it
      // via the event is cleaner as App.jsx controls the user state.
      // window.location.href = '/login'; // Or trigger a router navigation
      
      // You might want to reject the promise to let the calling code know the request failed.
      // However, if you want to "swallow" the error after handling logout, you might not re-throw.
      // For now, let's re-throw so the original caller knows.
      return Promise.reject(error); 
    }
    return Promise.reject(error);
  }
);

export default api;
